package com.networkmonitor.service;
import com.networkmonitor.dto.SystemReportDto;import com.networkmonitor.entity.*;import com.networkmonitor.repository.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;
@Service public class ReportService{private final DeviceRepository devices;private final MonitoringMetricRepository metrics;private final AlertRepository alerts;public ReportService(DeviceRepository d,MonitoringMetricRepository m,AlertRepository a){devices=d;metrics=m;alerts=a;}@Transactional(readOnly=true)public SystemReportDto generateSystemSummaryReport(){List<Device> ds=devices.findAll();int total=ds.size(),online=(int)ds.stream().filter(d->d.getStatus()==DeviceStatus.ONLINE).count();List<MonitoringMetric> ms=metrics.findAll();double avg=ms.stream().filter(x->x.getLatencyMs()!=null).mapToDouble(MonitoringMetric::getLatencyMs).average().orElse(0);SystemReportDto r=new SystemReportDto();r.setTotalDevices(total);r.setOnlineDevices(online);r.setOfflineDevices((int)ds.stream().filter(d->d.getStatus()==DeviceStatus.OFFLINE).count());r.setSlaAvailabilityPercent(total==0?100:Math.round(online*1000.0/total)/10.0);r.setTotalMetricsCollected(metrics.count());r.setAverageSystemLatencyMs(Math.round(avg*100)/100.0);r.setActiveAlertsCount(alerts.findByIsResolvedFalseOrderByCreatedAtDesc().size());r.setTotalAlertsCount((int)alerts.count());return r;}@Transactional(readOnly=true)public String exportDevicesCsv(){StringBuilder s=new StringBuilder("ID,Name,IP Address,Hostname,Type,Vendor,Model,MAC Address,OS Clue,Status,Health,Monitoring Enabled,Scan Interval Seconds,Last Seen\n");for(Device d:devices.findAll())s.append(d.getId()).append(',').append(csv(d.getName())).append(',').append(csv(d.getIpAddress())).append(',').append(csv(d.getHostname())).append(',').append(d.getDeviceType()).append(',').append(csv(d.getVendor())).append(',').append(csv(d.getModel())).append(',').append(csv(d.getMacAddress())).append(',').append(csv(d.getOsClue())).append(',').append(d.getStatus()).append(',').append(d.getHealthStatus()).append(',').append(d.isMonitoringEnabled()).append(',').append(d.getScanInterval()).append(',').append(csv(String.valueOf(d.getLastSeenAt()))).append('\n');return s.toString();}private String csv(String x){if(x==null)return "";return x.contains(",")||x.contains("\"")||x.contains("\n")?"\""+x.replace("\"","\"\"")+"\"":x;}}
